package pe.edu.flores.service;
import java.util.*;
import java.time.*;
import java.math.*;
import java.util.stream.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.security.crypto.password.PasswordEncoder;
import pe.edu.flores.dao.SqlDao;
@Service
public class CatalogoService {
 public record Field(String name,String label,String type,boolean required){}
 public record Catalog(String table,String title,List<Field> fields){}
 private final SqlDao db;private final IdentityService identity;private final PasswordEncoder encoder;private final Clock clock;
 public final Map<String,Catalog> catalogs=new LinkedHashMap<>();
 public CatalogoService(SqlDao db,IdentityService identity,PasswordEncoder encoder,Clock clock){this.db=db;this.identity=identity;this.encoder=encoder;this.clock=clock;
  define("agencias","agencia","Agencias","nombre|Nombre|text|1;ciudad|Ciudad|text|1;direccion|Dirección|text|0;telefono|Teléfono|text|0;activo|Activa|boolean|1");
  define("empleados","empleado","Personal","agencia_id|Agencia|agencias|1;nombres|Nombres|text|1;apellidos|Apellidos|text|1;documento|Documento|text|1;cargo|Cargo|cargo|1;activo|Activo|boolean|1");
  define("pasajeros","pasajero","Pasajeros","tipo_documento|Tipo de documento|documento|1;documento|Número de documento|text|1;nombres|Nombres|text|1;apellidos|Apellidos|text|1;telefono|Teléfono|text|0;correo|Correo|email|0");
  define("rutas","ruta","Rutas","origen|Origen|text|1;destino|Destino|text|1;distancia_km|Distancia en km|decimal|1;duracion_min|Duración en minutos|number|1;activo|Activa|boolean|1");
  define("buses","bus","Buses","placa|Placa|text|1;marca|Marca|text|1;modelo|Modelo|text|0;capacidad|Capacidad|number|1;soat_hasta|SOAT vigente hasta|date|1;revision_hasta|Revisión técnica hasta|date|1;estado|Estado|bus_estado|1");
  define("conductores","conductor","Conductores","nombres|Nombres|text|1;apellidos|Apellidos|text|1;licencia|Licencia|text|1;categoria|Categoría|text|1;vencimiento|Vencimiento de licencia|date|1;activo|Activo|boolean|1");
  define("viajes","viaje","Programación de viajes","ruta_id|Ruta|rutas|1;bus_id|Bus|buses|1;conductor_id|Conductor|conductores|1;salida|Fecha y hora de salida|datetime-local|1;precio|Tarifa S/|decimal|1;estado|Estado|viaje_estado|1");
  define("promociones","promocion","Promociones","nombre|Nombre|text|1;codigo|Código|text|1;tipo|Tipo de descuento|promocion_tipo|1;valor|Valor|decimal|1;desde|Vigente desde|date|1;hasta|Vigente hasta|date|1;activo|Activa|boolean|1");
 }
 private void define(String key,String table,String title,String spec){catalogs.put(key,new Catalog(table,title,Arrays.stream(spec.split(";")).map(x->{String[]a=x.split("\\|");return new Field(a[0],a[1],a[2],"1".equals(a[3]));}).toList()));}
 public Catalog catalog(String key){var c=catalogs.get(key);if(c==null)throw new BusinessException("Catálogo no permitido");return c;}
 public Map<String,Catalog> metadata(){return Collections.unmodifiableMap(catalogs);}
 public List<Map<String,Object>> list(String key){return db.list("SELECT * FROM "+catalog(key).table()+" ORDER BY id DESC");}
 private Object convert(Field f,Object v){try{if(v==null||v.toString().isBlank()){if(f.required())throw new BusinessException("Complete "+f.label());return null;}String s=v.toString().trim();if(s.length()>180)throw new BusinessException("Campo demasiado largo: "+f.label());return switch(f.type()){case "boolean" ->{if(!Set.of("true","false").contains(s))throw new BusinessException("Valor lógico inválido");yield Boolean.parseBoolean(s);}case "number","agencias","buses","conductores","rutas"->Long.parseLong(s);case "decimal"->new BigDecimal(s).setScale(2,RoundingMode.HALF_UP);case "date"->LocalDate.parse(s);case "datetime-local"->LocalDateTime.parse(s);default->s;};}catch(BusinessException e){throw e;}catch(Exception e){throw new BusinessException("Revise el formato de "+f.label());}}
 @Transactional public long save(String key,Long id,Map<String,Object> payload){Catalog c=catalog(key);Map<String,Object> values=new LinkedHashMap<>();if(id!=null)values.putAll(db.one("SELECT * FROM "+c.table()+" WHERE id=?",id));Set<String> allowed=c.fields().stream().map(Field::name).collect(Collectors.toSet());for(String k:payload.keySet())if(!allowed.contains(k))throw new BusinessException("Campo no permitido: "+k);for(Field f:c.fields()){if(payload.containsKey(f.name()))values.put(f.name(),convert(f,payload.get(f.name())));else if(id==null)values.put(f.name(),convert(f,null));}validate(key,id,values);List<String> cols=c.fields().stream().map(Field::name).toList();Object[] args=cols.stream().map(values::get).toArray();long result;
  if(id==null){result=db.insert("INSERT INTO "+c.table()+" ("+String.join(",",cols)+") VALUES ("+String.join(",",Collections.nCopies(cols.size(),"?"))+")",args);if(key.equals("pasajeros"))db.update("INSERT INTO cuenta_fidelizacion(pasajero_id) VALUES(?)",result);if(key.equals("buses")){int n=((Number)values.get("capacidad")).intValue();for(int i=1;i<=n;i++)db.update("INSERT INTO asiento(bus_id,numero,piso,tipo) VALUES(?,?,?,?)",result,i,i<=12?1:2,i<=12?"CAMA":"SEMICAMA");}if(key.equals("viajes"))db.update("INSERT INTO reserva(viaje_id,asiento_id) SELECT ?,id FROM asiento WHERE bus_id=?",result,values.get("bus_id"));}
  else{List<Object> a=new ArrayList<>(Arrays.asList(args));a.add(id);db.update("UPDATE "+c.table()+" SET "+cols.stream().map(x->x+"=?").collect(Collectors.joining(","))+" WHERE id=?",a.toArray());result=id;if(key.equals("viajes")){var oldBus=db.one("SELECT COUNT(*) AS n FROM reserva r JOIN asiento a ON a.id=r.asiento_id WHERE r.viaje_id=? AND a.bus_id<>?",id,values.get("bus_id"));if(SqlDao.id(oldBus,"n")>0){db.update("DELETE FROM reserva WHERE viaje_id=?",id);db.update("INSERT INTO reserva(viaje_id,asiento_id) SELECT ?,id FROM asiento WHERE bus_id=?",id,values.get("bus_id"));}}}
  db.audit(identity.username(),id==null?"CREAR_CATALOGO":"EDITAR_CATALOGO",key+" #"+result);return result;
 }
 private void positive(Map<String,Object>m,String key){if(new BigDecimal(m.get(key).toString()).signum()<=0)throw new BusinessException("El campo "+key+" debe ser mayor que cero");}
 private LocalDate date(Object o){return o instanceof java.sql.Date d?d.toLocalDate():o instanceof LocalDate d?d:LocalDate.parse(o.toString());}
 private LocalDateTime time(Object o){return o instanceof java.sql.Timestamp d?d.toLocalDateTime():o instanceof LocalDateTime d?d:LocalDateTime.parse(o.toString());}
 private void validate(String key,Long id,Map<String,Object>m){
  if(key.equals("pasajeros")){String type=m.get("tipo_documento").toString(),doc=m.get("documento").toString();if(!Set.of("DNI","CE","PASAPORTE").contains(type)||!(type.equals("DNI")?doc.matches("\\d{8}"):doc.matches("[A-Za-z0-9]{6,15}")))throw new BusinessException("Documento inválido. DNI: ocho dígitos. CE o pasaporte: de seis a quince caracteres");if(m.get("correo")!=null&&!m.get("correo").toString().matches("[^\\s@]+@[^\\s@]+\\.[^\\s@]+"))throw new BusinessException("Correo inválido");}
  if(key.equals("rutas")){positive(m,"distancia_km");positive(m,"duracion_min");if(m.get("origen").toString().equalsIgnoreCase(m.get("destino").toString()))throw new BusinessException("El origen y destino deben ser diferentes");}
  if(key.equals("empleados")&&!Set.of("ADMIN","VENDEDOR","CONTROLADOR","JEFE_OPERACIONES").contains(m.get("cargo")))throw new BusinessException("Cargo no permitido");
  if(key.equals("buses")){int n=((Number)m.get("capacidad")).intValue();if(n<1||n>60)throw new BusinessException("La capacidad debe estar entre 1 y 60");if(id!=null&&n!=SqlDao.id(db.one("SELECT capacidad FROM bus WHERE id=?",id),"capacidad"))throw new BusinessException("La capacidad no puede cambiar después de crear los asientos");if(!Set.of("OPERATIVO","MANTENIMIENTO","BAJA").contains(m.get("estado")))throw new BusinessException("Estado de bus inválido");}
  if(key.equals("promociones")){positive(m,"valor");m.put("codigo",m.get("codigo").toString().toUpperCase(Locale.ROOT));if(!Set.of("PORCENTAJE","MONTO_FIJO").contains(m.get("tipo")))throw new BusinessException("Tipo de promoción inválido");if("PORCENTAJE".equals(m.get("tipo"))&&new BigDecimal(m.get("valor").toString()).compareTo(new BigDecimal("100"))>0)throw new BusinessException("El porcentaje no puede superar 100");if(date(m.get("hasta")).isBefore(date(m.get("desde"))))throw new BusinessException("La fecha final precede a la inicial");}
  if(key.equals("viajes")){
   positive(m,"precio");if(!Set.of("PROGRAMADO","EN_EMBARQUE","EN_RUTA","FINALIZADO","CANCELADO").contains(m.get("estado")))throw new BusinessException("Estado de viaje inválido");var departure=time(m.get("salida"));var b=db.one("SELECT * FROM bus WHERE id=? FOR UPDATE",m.get("bus_id"));var driver=db.one("SELECT * FROM conductor WHERE id=? FOR UPDATE",m.get("conductor_id"));var route=db.one("SELECT * FROM ruta WHERE id=?",m.get("ruta_id"));if(!Boolean.TRUE.equals(route.get("activo")))throw new BusinessException("La ruta está desactivada");
   if(!"OPERATIVO".equals(b.get("estado"))||date(b.get("soat_hasta")).isBefore(departure.toLocalDate())||date(b.get("revision_hasta")).isBefore(departure.toLocalDate())||!Boolean.TRUE.equals(driver.get("activo"))||date(driver.get("vencimiento")).isBefore(departure.toLocalDate()))throw new BusinessException("SOAT, revisión, licencia o estado operativo no habilitados");
   if(id==null&&(!departure.isAfter(LocalDateTime.now(clock))||!"PROGRAMADO".equals(m.get("estado"))))throw new BusinessException("Un viaje nuevo debe ser futuro y PROGRAMADO");
   if(id!=null){var old=db.one("SELECT * FROM viaje WHERE id=? FOR UPDATE",id);boolean assigned=db.count("SELECT COUNT(*) FROM boleto WHERE viaje_id=? AND estado<>'ANULADO'",id)>0||db.count("SELECT COUNT(*) FROM reserva WHERE viaje_id=? AND vence>?",id,LocalDateTime.now(clock))>0;boolean changed=!Objects.equals(m.get("bus_id").toString(),old.get("bus_id").toString())||!Objects.equals(m.get("ruta_id").toString(),old.get("ruta_id").toString())||!Objects.equals(m.get("conductor_id").toString(),old.get("conductor_id").toString())||!departure.equals(time(old.get("salida")));if(assigned&&changed)throw new BusinessException("El viaje tiene boletos o reservas; anule o reprograme antes de cambiar su asignación");if("CANCELADO".equals(m.get("estado"))&&assigned)throw new BusinessException("Anule los boletos y libere reservas antes de cancelar el viaje");var order=Map.of("PROGRAMADO",0,"EN_EMBARQUE",1,"EN_RUTA",2,"FINALIZADO",3,"CANCELADO",4);if(order.get(m.get("estado"))<order.get(old.get("estado")))throw new BusinessException("El estado del viaje no puede retroceder");}
   if(!"CANCELADO".equals(m.get("estado"))){var others=db.list("SELECT v.id,v.salida,r.duracion_min FROM viaje v JOIN ruta r ON r.id=v.ruta_id WHERE (v.bus_id=? OR v.conductor_id=?) AND v.estado<>'CANCELADO' AND v.id<>?",m.get("bus_id"),m.get("conductor_id"),id==null?-1L:id);var end=departure.plusMinutes(SqlDao.id(route,"duracion_min"));for(var v:others){var start=time(v.get("salida"));var finish=start.plusMinutes(SqlDao.id(v,"duracion_min"));if(departure.isBefore(finish)&&end.isAfter(start))throw new BusinessException("Bus o conductor asignado a un viaje que se superpone");}}
  }
 }
 @Transactional public void user(Map<String,Object> data){String name=Objects.toString(data.get("usuario"),"").trim(),pass=Objects.toString(data.get("clave"),""),role=Objects.toString(data.get("rol"),"");if(!name.matches("[A-Za-z0-9_.-]{3,40}")||pass.length()<10||pass.length()>72||!Set.of("ADMIN","VENDEDOR","CONTROLADOR","JEFE_OPERACIONES","PASAJERO").contains(role))throw new BusinessException("Usuario de 3 a 40 caracteres y clave de 10 a 72 caracteres; seleccione un rol válido");Long employee=data.get("empleado_id")==null?null:Long.valueOf(data.get("empleado_id").toString());Long passenger=data.get("pasajero_id")==null?null:Long.valueOf(data.get("pasajero_id").toString());if(role.equals("PASAJERO")){if(passenger==null)throw new BusinessException("Seleccione un pasajero");db.one("SELECT id FROM pasajero WHERE id=?",passenger);employee=null;}else{if(employee==null)throw new BusinessException("Seleccione un empleado");var e=db.one("SELECT * FROM empleado WHERE id=?",employee);if(!Boolean.TRUE.equals(e.get("activo")))throw new BusinessException("El empleado está desactivado");passenger=null;}db.update("INSERT INTO usuario(usuario,clave_hash,rol,empleado_id,pasajero_id) VALUES(?,?,?,?,?)",name,encoder.encode(pass),role,employee,passenger);db.audit(identity.username(),"USUARIO_CREADO",name+"; rol="+role);}
 @Transactional public void toggleUser(long id,boolean active){var u=db.one("SELECT * FROM usuario WHERE id=? FOR UPDATE",id);if(u.get("usuario").equals(identity.username()))throw new BusinessException("No puede desactivar su propia cuenta");db.update("UPDATE usuario SET activo=? WHERE id=?",active,id);db.audit(identity.username(),"USUARIO_ESTADO",u.get("usuario")+"; activo="+active);}
 @Transactional public void changePassword(long id,String password){if(password==null||password.length()<10||password.length()>72)throw new BusinessException("Clave de 10 a 72 caracteres");db.update("UPDATE usuario SET clave_hash=?,intentos=0,bloqueado_hasta=NULL WHERE id=?",encoder.encode(password),id);db.audit(identity.username(),"CAMBIO_CLAVE","Usuario #"+id);}
}
